const roleKey = "userRole";
const username = "alexandra";

// Object literal with shorthand properties and computed property keys
const user = {
  username, // Shorthand for username: username
  age: 26,
  [roleKey]: "administrator", // Computed dynamic property name
  greet() {
    return `Hello from ${this.username}`;
  }
};

// Array creation via Array.from and Array.of
const consecutiveNumbers = Array.from({ length: 5 }, (_, index) => index + 1);

console.log(user[roleKey]);          // 'administrator'
console.log(consecutiveNumbers);     // [1, 2, 3, 4, 5]

const products = [
  { name: "Laptop", price: 1200, inStock: true },
  { name: "Mouse", price: 25, inStock: false },
  { name: "Keyboard", price: 80, inStock: true }
];

// 1. Filter: extract items in stock
const available = products.filter(p => p.inStock);

// 2. Map: extract names
const productNames = available.map(p => p.name);

// 3. Reduce: calculate total inventory value
const totalStockValue = available.reduce((acc, p) => acc + p.price, 0);

console.log("Available Items:", productNames); // ['Laptop', 'Keyboard']
console.log("Total Value: $", totalStockValue); // 1280

// 4. Object.entries
const settings = { theme: "dark", notifications: true };
for (const [key, value] of Object.entries(settings)) {
  console.log(`${key}: ${value}`);
}

const config = {
  apiHost: "api.mysite.com",
  port: 8080,
  protocol: "https",
  timeout: 5000
};

// Object destructuring with renaming and default values
const { apiHost: serverUrl, port, timeout = 3000, maxRetries = 3 } = config;
console.log(`Target: ${serverUrl}:${port}, Max Retries: ${maxRetries}`);

// Array destructuring with rest parameter
const colors = ["red", "green", "blue", "orange", "purple"];
const [primaryColor, secondaryColor, ...otherColors] = colors;

console.log(`Primary: ${primaryColor}`);     // 'red'
console.log(`Others:`, otherColors);        // ['blue', 'orange', 'purple']
